import {checkFormatting} from './format-model.mjs';
import {ruleSummary} from './format-presets.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export function createFormatReport({item,document,rules,verification=null,service='check',generatedAt=new Date().toISOString()}){const issues=checkFormatting(document,rules),excluded=document.paragraphs.filter(p=>p.excluded===true).length;return {format:'paperknow-format-report',version:1,title:item.title||'论文格式检查',fileName:item.fileName||'',example:item.example===true,generatedAt,service,rules:{...rules},summary:{paragraphs:document.paragraphs.length,excludedParagraphs:excluded,characters:document.chars||document.paragraphs.reduce((n,p)=>n+p.text.length,0),originalIssues:issues.length,unknown:issues.filter(item=>item.status==='unknown').length,outputVerified:Array.isArray(verification),remainingIssues:Array.isArray(verification)?verification.length:null},issues:issues.map(issue=>({...issue,location:issue.index!=null?'段落 '+(issue.index+1):'第 '+(issue.section+1)+' 节',excerpt:issue.index!=null?document.paragraphs[issue.index].text.slice(0,120):''})),verification:Array.isArray(verification)?structuredClone(verification):null,warnings:[...(document.warnings||[])],scope:'检查与整理选中的顶层正文段落及所选分节页边距。标记为保留原样的段落不修改；图片、表格、公式、页眉页脚、批注及目录域不自动调整。实际分页、目录更新、参考文献著录请在Word中核对。'};}
export function formatReportHtml(report){const {summary}=report,title=report.title+' · 格式'+(summary.outputVerified?'排版报告':'检测报告');return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><title>${esc(title)}</title><style>body{font:15px/1.7 system-ui,sans-serif;color:#203250;background:#f3f6fc;margin:0}main{max-width:1050px;margin:28px auto;background:white;border:1px solid #dce5f4;border-radius:18px;padding:34px}header{border-bottom:2px solid #316cff;padding-bottom:20px}.brand{font-weight:800;color:#316cff}h1{font-size:27px;margin:8px 0}.muted{color:#667897}.stats{display:flex;flex-wrap:wrap;gap:14px;margin:24px 0}.stats div{flex:1;min-width:130px;border:1px solid #dce5f4;background:#f7faff;border-radius:12px;padding:14px}.stats b{display:block;font-size:25px}h2{font-size:18px;margin-top:28px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #dce5f4;padding:10px;overflow-wrap:anywhere}th{background:#f4f7fd}th:first-child{width:16%}th:nth-child(2){width:16%}.note{padding:16px;background:#f3f7ff;border-radius:10px}.status{font-weight:700;color:#285bd2}@media print{body{background:white}main{border:0;margin:0;padding:0;max-width:none}tr{break-inside:avoid}h2{break-after:avoid}.print-help{display:none}}</style></head><body><main><header><span class="brand">PaperKnow</span><h1>${esc(title)}</h1><p class="muted">${esc(report.fileName||'示例文档')} · ${esc(report.generatedAt)}${report.example?' · 示例体验':''}</p><p class="print-help">可使用浏览器“打印”保存为PDF。此报告来自所选规则的实际检查。</p></header><section class="stats"><div>原文段落<b>${summary.paragraphs}</b></div><div>保留原样<b>${summary.excludedParagraphs}</b></div><div>原件格式差异<b>${summary.originalIssues}</b></div><div>${summary.outputVerified?'副本剩余差异':'待确认设置'}<b>${summary.outputVerified?summary.remainingIssues:summary.unknown}</b></div></section><p class="status">${summary.outputVerified?'已生成并重新读取排版副本，以下清单保留原件差异以便核对。':'本次仅检测格式，尚未修改原文档。'}</p><h2>本次规则</h2><p>${esc(ruleSummary(report.rules))}</p><p>标题字号：${[1,2,3].map(n=>n+'级 '+report.rules['h'+n]+'pt').join(' / ')}。应用范围：${[['body','正文'],['headings','标题'],['margins','分节页边距']].filter(([key])=>report.rules[key]).map(([,name])=>name).join('、')}。</p><h2>原件问题与位置</h2><table><thead><tr><th>位置</th><th>项目</th><th>原件 → 目标</th><th>正文节选</th></tr></thead><tbody>${report.issues.map(issue=>`<tr><td>${esc(issue.location)}</td><td>${esc(issue.label)}<br>${issue.status==='unknown'?'需确认':'规则差异'}</td><td>${esc(issue.current)} → ${esc(issue.target)}</td><td>${esc(issue.excerpt)}</td></tr>`).join('')||'<tr><td colspan="4">当前检查范围内未发现格式差异。</td></tr>'}</tbody></table>${summary.outputVerified?`<h2>副本复查</h2><p>${summary.remainingIssues?'仍有 '+summary.remainingIssues+' 项需要核对。':'已选规则范围内未发现差异。'}</p>`:''}<h2>处理范围</h2><div class="note">${esc(report.scope)}${report.warnings.length?'<ul>'+report.warnings.map(warning=>'<li>'+esc(warning)+'</li>').join('')+'</ul>':''}</div><p class="muted">格式规则由用户确认；本报告不代表学校或期刊审核结论。</p></main></body></html>`;}
